class MinHeap:
    def __init__(self):
        self.heap = []

    # 返回堆中的结点数
    def size(self):
            return len(self.heap)

    # 检查堆是否为空
    def is_empty(self):
        return len(self.heap) == 0

    # 堆的字符串表示
    def __str__(self):
        return str(self.heap)

    # 交换堆值
    def swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    # 计算结点的父结点的索引
    def parent(self, index):
        return (index - 1) // 2

    # 计算结点的左子结点的索引
    def left_child(self, index):
        return 2 * index + 1

    # 计算结点的右子结点的索引
    def right_child(self, index):
        return 2 * index + 2

    # 检查给定索引处的结点是否有父结点
    def has_parent(self, index):
        return self.parent(index) >= 0

    # 检查给定索引处的结点是否有左子结点
    def has_left_child(self, index):
        return self.left_child(index) < len(self.heap)

    # 检查给定索引处的结点是否有右子结点
    def has_right_child(self, index):
        return self.right_child(index) < len(self.heap)

    # 堆化
    def heapify(self, array):
        self.heap = array
        for i in range(len(self.heap) - 1, -1, -1):
            if  self.has_left_child(i):
                self.heapify_down(i)

    # 向下堆化
    def heapify_down(self, index):
        if not self.has_left_child(index):
            return
        smaller_child_index = self.left_child(index)
        if self.has_right_child(index): 
            if self.heap[self.right_child(index)] < self.heap[smaller_child_index]:
                smaller_child_index = self.right_child(index)
        if self.heap[index] > self.heap[smaller_child_index]:
            self.swap(index, smaller_child_index)
        if self.has_left_child(smaller_child_index):
            self.heapify_down(smaller_child_index)

    # 向上堆化
    def heapify_up(self, index):
        if self.has_parent(index): 
            parent_index = self.parent(index)
            # 将值与其父结点进行比较，并在必要时进行交换
            if self.heap[index] < self.heap[self.parent(index)]:
                parent_index = self.parent(index)
                self.swap(index, parent_index)
                # 为父结点运行代码                
                if self.has_parent(parent_index):
                    self.heapify_up(parent_index)

    # 插入堆
    def insert(self, value):
        self.heap.append(value)
        self.heapify_up(self.size() - 1)

    # 从堆中提取最小值
    def extract_min(self):
        min = self.heap[0]
        if self.size() == 1:    
            self.heap = []
            return min
        self.heap[0] = self.heap[-1] 
        self.heap.pop()
        self.heapify_down(0)
        return min

    # 查找
    def peek(self):
        return self.heap[0]

